import {TextureViewer} from './texture-viewer.js';
import {decodeLightmapPixels,lightmapFloat} from './lightmap-assets.js';
export class LightmapEditor{
 constructor(element,doc,hooks){this.el=element;this.doc=doc;this.hooks=hooks;this.page=0;this.exposure=1;this.generation=0;const d=element.ownerDocument;element.replaceChildren();const header=d.createElement('header');header.className='document-toolbar';const title=d.createElement('strong');title.textContent=doc.data.name+' · 간접광';const select=d.createElement('select');select.dataset.lightmapPage='';select.setAttribute('aria-label','라이트맵 페이지');doc.data.maps.forEach((m,i)=>{const option=d.createElement('option');option.value=i;option.textContent='페이지 '+i+' · '+m.width+' × '+m.height;select.append(option);});const label=d.createElement('label');label.textContent='노출 ';const exposure=d.createElement('input');exposure.type='number';exposure.min='.001';exposure.max='1000';exposure.step='.1';exposure.value='1';exposure.dataset.lightmapExposure='';exposure.setAttribute('aria-label','라이트맵 미리보기 노출');label.append(exposure);const output=d.createElement('output');output.textContent=doc.data.bindings.length+' 수신 메시';header.append(title,select,label,output);element.append(header);this.viewer=new TextureViewer(element,{sources:[''],fileUrl:p=>p,error:hooks.error});element.hbTextureViewer=this;select.onchange=()=>this.set({index:Number(select.value)});exposure.onchange=()=>this.set({exposure:Number(exposure.value)});const pick=this.viewer.pick.bind(this.viewer);this.viewer.pick=(x,y)=>{const result=pick(x,y);if(result&&this.cache){const at=((this.cache.height-1-y)*this.cache.width+x)*4;result.linear=[0,1,2,3].map(c=>lightmapFloat(this.cache.pixels[at+c]));this.viewer.pixel=result;this.viewer.root.querySelector('[data-texture-pixel]').textContent=x+', '+y+' · Linear '+result.linear.slice(0,3).map(n=>n.toPrecision(5)).join(' ');}return result;};this.refresh().catch(e=>{if(!this.disposed)hooks.error(e.message);});}
 async refresh(){const epoch=++this.generation,map=this.doc.data.maps[this.page];if(!map)return;let cache=this.cache;if(!cache||cache.index!==this.page){cache={index:this.page,width:map.width,height:map.height,pixels:await decodeLightmapPixels(map)};}if(this.disposed||epoch!==this.generation)return;this.cache=cache;const bytes=new Uint8ClampedArray(map.width*map.height*4),srgb=n=>n<=.0031308?n*12.92:1.055*n**(1/2.4)-.055;for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){const at=(y*map.width+x)*4,source=((map.height-1-y)*map.width+x)*4;for(let c=0;c<3;c++){const v=lightmapFloat(cache.pixels[source+c])*this.exposure;bytes[at+c]=Math.round(Math.max(0,Math.min(1,srgb(v/(1+v))))*255);}bytes[at+3]=255;}const canvas=this.el.ownerDocument.createElement('canvas');canvas.width=map.width;canvas.height=map.height;canvas.getContext('2d').putImageData(new ImageData(bytes,map.width,map.height),0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve));canvas.width=canvas.height=0;if(!blob)throw Error('라이트맵 미리보기를 만들 수 없어요.');if(this.disposed||epoch!==this.generation)return;const url=URL.createObjectURL(blob),old=this.url;this.url=url;this.viewer.sources=[url];await this.viewer.load();if(old)URL.revokeObjectURL(old);}
 set(settings){const {index=this.page,exposure=this.exposure,...view}=settings;if(!Number.isInteger(index)||index<0||index>=Math.max(1,this.doc.data.maps.length)||!Number.isFinite(exposure)||exposure<.001||exposure>1000)throw Error('라이트맵 페이지·미리보기 노출을 확인하세요.');const refresh=index!==this.page||exposure!==this.exposure;this.page=index;this.exposure=exposure;this.el.querySelector('[data-lightmap-page]').value=index;this.el.querySelector('[data-lightmap-exposure]').value=exposure;if(Object.keys(view).length)this.viewer.set(view);if(refresh)this.refresh().catch(e=>{if(!this.disposed)this.hooks.error(e.message);});return this.snapshot();}
 pick(x,y){return this.viewer.pick(x,y);}
 snapshot(){return{...this.viewer.snapshot(),index:this.page,exposure:this.exposure,pages:this.doc.data.maps.length,bindings:this.doc.data.bindings.length,linear:true};}
 dispose(){if(this.disposed)return;this.disposed=true;this.generation++;this.viewer.dispose();if(this.url)URL.revokeObjectURL(this.url);this.cache=null;}
}
